import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"Диагностика и ошибки компилятора","description":"","frontmatter":{},"headers":[],"relativePath":"ru/mlua/diagnostics.md","filePath":"ru/mlua/diagnostics.md","lastUpdated":1789328014000}'),r={name:"ru/mlua/diagnostics.md"};function c(n,t,s,i,h,l){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="диагностика-и-ошибки-компилятора" tabindex="-1">Диагностика и ошибки компилятора <a class="header-anchor" href="#диагностика-и-ошибки-компилятора" aria-label="Permalink to &quot;Диагностика и ошибки компилятора&quot;">​</a></h1><p>Каждое диагностическое сообщение содержит уникальный код ошибки, позицию в исходном коде и текстовое описание. Префикс кода указывает этап конвейера компиляции, на котором была обнаружена проблема.</p><h2 id="диапазоны-кодов" tabindex="-1">Диапазоны кодов <a class="header-anchor" href="#диапазоны-кодов" aria-label="Permalink to &quot;Диапазоны кодов&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Диапазон</th><th>Этап</th><th>Значение</th></tr></thead><tbody><tr><td><code>MLUA1xxx</code></td><td>Лексер</td><td>Ошибки токенов: незакрытые строки, некорректные числа, недопустимые escape-последовательности</td></tr><tr><td><code>MLUA3xxx</code></td><td>Парсер</td><td>Грамматические ошибки: пропущенный <code>end</code>, неожиданный токен, неверный синтаксис</td></tr><tr><td><code>MLUA42xx</code></td><td>Доступ</td><td>Нарушения видимости <code>private</code> и <code>protected</code> членов</td></tr><tr><td><code>MLUA43xx</code></td><td>Объявления</td><td>Ошибки <code>override</code>, <code>final</code>, <code>abstract</code> или реализации интерфейсов</td></tr><tr><td><code>MLUA44xx</code></td><td>Типы</td><td>Неизвестные члены, несоответствие типов аргументов, недопустимые операторы</td></tr></tbody></table><p>Ошибки всегда выводятся, начиная с <em>самого раннего</em> упавшего этапа. Например, скрипт с лексической ошибкой даже не начинает парситься или проверяться по типам, поскольку последующие стадии требуют успешного прохождения предыдущих.</p><h2 id="часто-встречающиеся-коды" tabindex="-1">Часто встречающиеся коды <a class="header-anchor" href="#часто-встречающиеся-коды" aria-label="Permalink to &quot;Часто встречающиеся коды&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Код</th><th>Сообщение</th><th>Причина</th></tr></thead><tbody><tr><td><code>MLUA3001</code></td><td>unexpected token after chunk body</td><td>Лишний <code>end</code> или блок, закрытый дважды</td></tr><tr><td><code>MLUA3013</code></td><td>unexpected token in type body</td><td>Инструкция, помещённая прямо в тело класса или интерфейса</td></tr><tr><td><code>MLUA3017</code></td><td>expected an expression</td><td>Ключевое слово объявления использовано там, где ожидалось значение</td></tr><tr><td><code>MLUA4206</code></td><td>member is private to a class</td><td>Чтение закрытого члена извне класса</td></tr><tr><td><code>MLUA4207</code></td><td>member is protected in a class</td><td>Чтение защищённого члена вне иерархии классов</td></tr><tr><td><code>MLUA4403</code></td><td>operator applied to the wrong type</td><td>Например, оператор длины <code>#</code> применён к числу</td></tr><tr><td><code>MLUA4404</code></td><td>cannot assign one type to another</td><td>Тип значения не соответствует аннотации переменной</td></tr><tr><td><code>MLUA4410</code></td><td>type has no member named ...</td><td>Опечатка или обращение к необъявленному полю / методу</td></tr><tr><td><code>MLUA4411</code></td><td>argument expects one type but received another</td><td>Переданный аргумент не соответствует объявленному типу параметра</td></tr><tr><td><code>MLUA4412</code></td><td>enum member is read only</td><td>Попытка изменить значение элемента перечисления</td></tr></tbody></table><h2 id="формат-диагностического-сообщения" tabindex="-1">Формат диагностического сообщения <a class="header-anchor" href="#формат-диагностического-сообщения" aria-label="Permalink to &quot;Формат диагностического сообщения&quot;">​</a></h2><p>Сообщения об ошибках имеют постоянный формат:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=test:24:52 MLUA4206: secret is private to Base</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Часть</th><th>Значение</th></tr></thead><tbody><tr><td><code>=test</code></td><td>Имя чанка (файла)</td></tr><tr><td><code>24:52</code></td><td>Номер строки и колонки токена</td></tr><tr><td><code>MLUA4206</code></td><td>Код ошибки</td></tr><tr><td><em>(остаток)</em></td><td>Понятное объяснение ошибки</td></tr></tbody></table><p>Этот формат стабилен и удобен для парсинга редакторами и инструментами сборки.</p><h2 id="уровень-серьезности-severity" tabindex="-1">Уровень серьёзности (Severity) <a class="header-anchor" href="#уровень-серьезности-severity" aria-label="Permalink to &quot;Уровень серьёзности (Severity)&quot;">​</a></h2><p>У компилятора есть только один уровень критичности: <strong>ошибка (error)</strong>. Чанк хотя бы с одной диагностической ошибкой не запустится в игре - опечатка в имени поля, неверный <code>override</code> или несоответствие типов будут пойманы до того, как код начнёт исполняться, что исключает неожиданные падения игры посреди игровой сессии.</p><p>Предупреждений (warnings) и директив подавления ошибок нет. Если вам нужно отключить строгие проверки для конкретного значения, объявите его с типом <code>any</code> или <code>object</code> - это делает ослабление типизации явным в самом коде.</p><h2 id="строгии-анализ-и-выполнение-с-проверками-в-рантаиме" tabindex="-1">Строгий анализ и выполнение с проверками в рантайме <a class="header-anchor" href="#строгии-анализ-и-выполнение-с-проверками-в-рантаиме" aria-label="Permalink to &quot;Строгий анализ и выполнение с проверками в рантайме&quot;">​</a></h2><p>Строгий режим, используемый функцией <code>AnalyzeSource</code>, выдаёт ошибки для всех несоответствий типов и нарушений доступа. Режим <code>RuntimeChecked</code>, используемый во время обычного запуска, сохраняет синтаксические ошибки и проверки типов, но позволяет динамические поля через метатаблицы.</p>',17)])])}const m=d(r,[["render",c]]);export{b as __pageData,m as default};
